  width: 40px;
  height: 40px;
  border: 4px solid transparent;
  border-top-color: #ff0000;
  border-radius: 50%;
  animation: cursedSpin 0.8s linear infinite;
  position: relative;
}
.loading-spinner::after {
  content: "";
  position: absolute;
  top: -4px;
  left: -4px;
  width: 100%;
  height: 100%;
  border: 4px solid transparent;
  border-bottom-color: #0000ff;
  border-radius: 50%;
  animation: cursedSpin 1.2s linear reverse infinite;
}
```

